"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[443],{6721:e=>{e.exports=JSON.parse('{"functions":[{"name":"Say","desc":"Creates a speech bubble over Scag\'s head with the given text.\\n\\nYou can customize the text using the BBCode formatting system.\\n- `[b]bold[/b]` for bold text\\n- `[i]italic[/i]` for italic text\\n- `[u]underline[/u]` for underlined text\\n- `[color=red]red text[/color]` for colored text\\n- `[size=20]large text[/size]` for larger text\\n\\n```lua\\nScagRPC.Say(\\"hello!!\\")\\ntask.wait(2)\\nScagRPC.Say(\\"i am scag!\\")\\ntask.wait(1)\\nScagRPC.Say(\\"this is [b]SOOOO[/b] cool!\\")\\n```","params":[{"name":"text","desc":"","lua_type":"string"}],"returns":[],"function_type":"static","source":{"line":58,"path":"src/ScagRPC/init.luau"}},{"name":"SayPreset","desc":"Does the same action as [ScagRPC.Say], but is used internally by The Axolotl Sun to say preset lines of dialogue.\\n\\nWhile not intended for public use, you can view [Presets.Say] to see the available preset lines of dialogue.\\n\\n```lua\\nlocal Humanoid = script.Parent:WaitForChild(\\"Humanoid\\")\\n\\nfunction OnDeath()\\n\\tScagRPC.SayPreset(Presets.Say.player_died)\\nend\\n\\nHumanoid.Died:Connect(OnDeath)\\n```","params":[{"name":"presetId","desc":"","lua_type":"string"}],"returns":[],"function_type":"static","private":true,"source":{"line":80,"path":"src/ScagRPC/init.luau"}},{"name":"Fling","desc":"Flings Scag with a given force, or randomly if no force is provided.\\n\\n```lua\\n-- Fling in a specific direction\\nScagRPC.Fling(Vector2.new(10, 10))\\n\\n-- Fling in a random direction\\nScagRPC.Commands.Fling()\\n```","params":[{"name":"velocity","desc":"","lua_type":"Vector2?"}],"returns":[],"function_type":"static","source":{"line":97,"path":"src/ScagRPC/init.luau"}}],"properties":[],"types":[{"name":"Commands","desc":"The list of commands that can be sent to ScagJPT.","lua_type":"\\"say\\" | \\"fling\\" | \\"say_preset\\" | \\"set_image_preset\\" | \\"play_audio_preset\\"","source":{"line":6,"path":"src/ScagRPC/Types.luau"}}],"name":"ScagRPC","desc":"Adds functions to communicate with ScagJPT.","source":{"line":36,"path":"src/ScagRPC/init.luau"}}')}}]);